-- 0009_add_intake_review — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- intake_decision: client data (02-architecture §4). Staff see all rows; a client sees its own rows marked
-- visibility = 'client'; partners see nothing until a policy links rows to their assigned jobs or sites.
CREATE TABLE intake_decision (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL,
  visibility  text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz
);
CREATE INDEX intake_decision_client ON intake_decision (client_id);

ALTER TABLE intake_decision ENABLE ROW LEVEL SECURITY;
CREATE POLICY intake_decision_internal ON intake_decision FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY intake_decision_client_read ON intake_decision FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON intake_decision TO ocs_app;
